import json, glob, os
from pathlib import Path
from collections import Counter

ROOT = Path("bench/logs")
scores = []
def walk(o):
    if isinstance(o, dict):
        sk = o.get("sk_result")
        if isinstance(sk, dict):
            # look for a numeric score
            for key in ("sk","score","sk_score"):
                v = sk.get(key)
                if isinstance(v,(int,float)) and not isinstance(v,bool):
                    scores.append(float(v)); break
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)

files=0
for f in sorted(glob.glob("bench/logs/*/runner_state.json")):
    if os.path.getsize(f)>60_000_000: continue
    try:
        raw=open(f,errors="ignore").read()
        if "sk_result" not in raw: continue
        d=json.loads(raw)
    except Exception: continue
    files+=1; walk(d)

print("files:", files, "scores collected:", len(scores))
c=Counter(round(s,6) for s in scores)
for v,n in sorted(c.items()):
    print(f"  {v:>10}: {n}")

import json, glob, os
from collections import Counter
def walk_sk(o, acc):
    if isinstance(o, dict):
        sk=o.get("sk_result")
        if isinstance(sk, dict):
            for key in ("sk","score","sk_score"):
                v=sk.get(key)
                if isinstance(v,(int,float)) and not isinstance(v,bool):
                    acc.append(float(v)); break
        for v in o.values(): walk_sk(v,acc)
    elif isinstance(o,list):
        for v in o: walk_sk(v,acc)

scored=[]  # sk>0
for f in sorted(glob.glob("bench/logs/*/runner_state.json")):
    if os.path.getsize(f)>60_000_000: continue
    try:
        raw=open(f,errors="ignore").read()
        if "sk_result" not in raw: continue
        d=json.loads(raw)
    except Exception: continue
    acc=[]; walk_sk(d,acc)
    scored += [s for s in acc if s>0]

n=len(scored)
exact1 = sum(1 for s in scored if s==1.0)
at_or_above_074 = sum(1 for s in scored if s>=0.74)
print("scored (sk>0):", n)
print("exactly 1.0:", exact1, f"= {100*exact1/n:.2f}%")
print(">=0.74:", at_or_above_074, f"= {100*at_or_above_074/n:.2f}%")
print("min scored:", min(scored))
# discrimination ceiling: a threshold can separate at most the below-1.0 mass from the rest
print("max mass a gate can 'catch' (sk<1.0):", sum(1 for s in scored if s<1.0), f"= {100*(1-exact1/n):.2f}%")
# Wilson on the exactly-1.0 proportion
def wilson(k,n,z=1.959963984540054):
    p=k/n; d=1+z*z/n; c=p+z*z/(2*n); h=z*((p*(1-p)/n+z*z/(4*n*n))**0.5)
    return ((c-h)/d,(c+h)/d)
print("Wilson 95% on pile-at-1.0:", [round(x,4) for x in wilson(exact1,n)])
